package com.ias.finance;
import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.databind.json.JsonMapper;
import javax.sql.DataSource;
import java.util.*;
import static com.ias.finance.FeeGroup.*;

@RestController
public final class FinanceController {
 final DataSource source;final FinanceAccess access;
 static final JsonMapper JSON=JsonMapper.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 public FinanceController(DataSource source,FinanceAccess access){this.source=source;this.access=access;}
 @ModelAttribute public void noStore(jakarta.servlet.http.HttpServletResponse r){r.setHeader("Cache-Control","no-store");}
 JdbcFeeGroups store(HttpServletRequest r,FinanceAccess.Principal p){return new JdbcFeeGroups(source,access.bind(r,p));}
 static Map<String,Object> body(String raw,Set<String> required){if(raw==null||raw.length()>65536||raw.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw new Problem(413,"REQUEST_TOO_LARGE");try{Map<String,Object> b=JSON.readValue(raw,Map.class);if(!b.keySet().equals(required))throw new IllegalArgumentException();return b;}catch(Exception e){throw new Problem(400,"INVALID_REQUEST");}}
 static String text(Object v){if(!(v instanceof String s)||s.isBlank()||s.codePointCount(0,s.length())>1000||s.chars().anyMatch(Character::isISOControl))throw new Problem(400,"INVALID_REQUEST");return s;}
 static UUID id(Object v){String s=text(v);UUID id;try{id=UUID.fromString(s);}catch(Exception e){throw new Problem(400,"INVALID_ID");}if(!id.toString().equals(s))throw new Problem(400,"INVALID_ID");return id;}
 static long number(Object v){String s=text(v);if(!s.matches("0|[1-9][0-9]{0,18}"))throw new Problem(400,"INVALID_NUMBER");try{return Long.parseLong(s);}catch(Exception e){throw new Problem(400,"INVALID_NUMBER");}}
 static UUID key(Map<String,Object> b,HttpServletRequest r){UUID op=id(b.get("operationId"));if(!op.toString().equals(Chain.single(r,"Idempotency-Key")))throw new Problem(400,"INVALID_IDEMPOTENCY_KEY");return op;}
 @PostMapping("/api/finance/tickets/{ticket}/group") public Object open(@PathVariable String ticket,@RequestBody String raw,HttpServletRequest r)throws Exception{var b=body(raw,Set.of("operationId"));var op=key(b,r);var p=access.principal(r,true);var scope=access.scope(r,p,id(ticket));return safe(store(r,p).open(p.actor(),scope.owner(),op),p);}
 @GetMapping("/api/finance/tickets/{ticket}/group") public Object group(@PathVariable String ticket,HttpServletRequest r)throws Exception{var p=access.principal(r,false);var scope=access.scope(r,p,id(ticket));var state=store(r,p).read(p.actor(),scope.owner());return Map.of("groupId",scope.owner().faultGroupId().toString(),"version",Long.toString(state.version()));}
 @PostMapping("/api/finance/groups/{group}/quotes") public Object submit(@PathVariable String group,@RequestBody String raw,HttpServletRequest r)throws Exception{
  var b=body(raw,Set.of("operationId","quoteId","expectedVersion","ticketId","replaces","lines","chargesCustomer","pricingDescription"));UUID op=key(b,r);var p=access.principal(r,true);var store=store(r,p);var owner=store.owner(p.actor(),id(group));var scope=access.scope(r,p,id(b.get("ticketId")));if(!scope.owner().equals(owner))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");
  if(!(b.get("chargesCustomer") instanceof Boolean charged)||!(b.get("replaces") instanceof List<?> replacements)||!(b.get("lines") instanceof List<?> inputs)||inputs.isEmpty()||inputs.size()>50||replacements.size()>50)throw new Problem(400,"INVALID_REQUEST");
  var replaces=new HashSet<UUID>();for(Object v:replacements)if(!replaces.add(id(v)))throw new Problem(400,"DUPLICATE_LINE");var lines=new ArrayList<PlanLine>();var kinds=new HashMap<UUID,String>();var bindings=new HashMap<UUID,JdbcFeeGroups.PartBinding>();
  for(Object item:inputs){if(!(item instanceof Map<?,?> line)||!(line.keySet().equals(Set.of("id","amountCents","kind"))||line.keySet().equals(Set.of("id","amountCents","kind","partBinding"))))throw new Problem(400,"INVALID_REQUEST");UUID lineId=id(line.get("id"));String kind=text(line.get("kind"));if(kinds.putIfAbsent(lineId,kind)!=null)throw new Problem(400,"DUPLICATE_LINE");lines.add(new PlanLine(lineId,scope.ticket(),scope.round(),number(line.get("amountCents")),false));if(line.containsKey("partBinding")){if(!(line.get("partBinding") instanceof Map<?,?> part)||!part.keySet().equals(Set.of("approvalId","approvalVersion","warehouseId","partId","quantity","unitCode","allocationRule")))throw new Problem(400,"INVALID_REQUEST");bindings.put(lineId,new JdbcFeeGroups.PartBinding(id(part.get("approvalId")),number(part.get("approvalVersion")),number(part.get("warehouseId")),number(part.get("partId")),number(part.get("quantity")),text(part.get("unitCode")),text(part.get("allocationRule"))));}}
  var frozen=new JdbcQuoteSources(source,access.bind(r,p)).frozenRule(p.actor(),owner,op);var rule=frozen==null?access.rule(r):frozen;var command=new Submit(op,id(b.get("quoteId")),number(b.get("expectedVersion")),replaces,lines,rule);return safe(store.submit(p.actor(),owner,command,new JdbcFeeGroups.QuoteDetails(charged,text(b.get("pricingDescription")),kinds,bindings)),p);
 }
 @GetMapping("/api/finance/groups/{group}/quotes/{quote}") public Object quote(@PathVariable String group,@PathVariable String quote,HttpServletRequest r)throws Exception{var p=access.principal(r,false);var store=store(r,p);var owner=store.owner(p.actor(),id(group));var q=store.quote(p.actor(),owner,id(quote));var out=new LinkedHashMap<String,Object>();out.put("quoteId",q.command().applicationId().toString());out.put("quoteVersion",Long.toString(q.basis().groupVersion()));out.put("chargesCustomer",q.details().chargesCustomer());out.put("pricingDescription",q.details().pricingDescription());if(!q.details().partBindings().isEmpty())out.put("coverageVersion","2");out.put("lines",q.command().additions().stream().map(l->JdbcFeeGroups.coverageLine(l,q.details())).toList());out.putAll(store.quoteStatus(p.actor(),owner,id(quote)));if(p.type().equals("EMPLOYEE"))out.put("internalBasis",basis(q.basis()));return out;}
 @PostMapping("/api/finance/groups/{group}/quotes/{quote}/confirm") public Object confirm(@PathVariable String group,@PathVariable String quote,@RequestBody String raw,HttpServletRequest r)throws Exception{var b=body(raw,Set.of("operationId","expectedVersion","quoteVersion"));UUID op=key(b,r);var p=access.principal(r,true);var store=store(r,p);var owner=store.owner(p.actor(),id(group));return safe(store.confirm(p.actor(),owner,op,number(b.get("expectedVersion")),id(quote),number(b.get("quoteVersion"))),p);}
 @PostMapping("/api/finance/groups/{group}/quotes/{quote}/{decision:reject|withdraw}") public Object decide(@PathVariable String group,@PathVariable String quote,@PathVariable String decision,@RequestBody String raw,HttpServletRequest r)throws Exception{var b=body(raw,Set.of("operationId","expectedVersion","quoteVersion","reason"));UUID op=key(b,r);var p=access.principal(r,true);var store=store(r,p);var owner=store.owner(p.actor(),id(group));return safe(store.decide(p.actor(),owner,op,number(b.get("expectedVersion")),id(quote),number(b.get("quoteVersion")),decision.equals("reject")?"CUSTOMER_QUOTE_REJECTED":"QUOTE_WITHDRAWN",text(b.get("reason"))),p);}
 @GetMapping("/api/finance/groups/{group}/operations/{operation}") public Object operation(@PathVariable String group,@PathVariable String operation,HttpServletRequest r)throws Exception{var p=access.principal(r,false);var store=store(r,p);var owner=store.owner(p.actor(),id(group));return safe(store.operation(p.actor(),owner,id(operation)),p);}
 static Map<String,Object> safe(JdbcFeeGroups.Receipt receipt,FinanceAccess.Principal p){var out=new LinkedHashMap<String,Object>();out.put("operationId",receipt.operationId().toString());out.put("action",receipt.action());out.put("groupId",receipt.owner().faultGroupId().toString());out.put("groupVersion",Long.toString(receipt.groupVersion()));if(receipt.basis()!=null){out.put("quoteId",receipt.basis().applicationId().toString());if(p.type().equals("EMPLOYEE"))out.put("internalBasis",basis(receipt.basis()));}return out;}
 static Map<String,Object> basis(Basis b){var out=new LinkedHashMap<String,Object>();out.put("quoteVersion",Long.toString(b.groupVersion()));out.put("qCents",Long.toString(b.qCents()));out.put("cCents",Long.toString(b.cCents()));out.put("hCents",Long.toString(b.hCents()));out.put("bCents",Long.toString(b.bCents()));out.put("ruleVersion",b.rule().version());out.put("thresholdCents",Long.toString(b.rule().thresholdCents()));out.put("financialReviewRequired",b.financialReviewRequired());var f=b.firstFinanceTrigger();out.put("firstFinanceTrigger",f==null?null:Map.of("quoteId",f.applicationId().toString(),"ruleVersion",f.ruleVersion(),"groupVersion",Long.toString(f.groupVersion())));return out;}
}
